        sumWart[kat] += wart;
        if (wart > bestWart) { bestWart = wart; bestProd = nazwa; }
    }

    // a)
    cout << "a) Najdrozszy w kategorii:" << endl;
    for (auto &p : maxProd)
        cout << "   " << p.first << ": " << p.second
             << " (" << maxCena[p.first] << ")" << endl;

